function validate([hours]) {
  if (!Array.isArray(hours) || hours.length < 1 || hours.length > 100) return 'hours needs 1 to 100 values.';
  if (hours.some(v => !Number.isInteger(v) || v < 1 || v > 1000000000)) return 'Each value is a whole number from 1 to 10^9.';
  return null;
}

