function countCompleteDayPairs(hours) {
  // Count by remainder instead: a value with remainder r completes a day with every
  // earlier value whose remainder is (24 - r) % 24.
  const seen = new Array(24).fill(0);
  let pairs = 0;
  for (const h of hours) {
    pairs += seen[(24 - (h % 24)) % 24];
    seen[h % 24]++;
  }
  return pairs;
}

