function generate(rand, size) {
  const pick = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const n = size === 'large' ? 100 : pick(1, 10);
  // A few remainders and their complements make complete-day pairs common.
  const remainders = Array.from({ length: pick(1, 4) }, () => pick(0, 23));
  const hours = Array.from({ length: n }, () => {
    const base = rand() < 0.8 ? remainders[pick(0, remainders.length - 1)] : pick(0, 23);
    const remainder = rand() < 0.5 ? base : (24 - base) % 24;
    const days = size === 'large' ? pick(0, 41666665) : pick(0, 5);
    const value = days * 24 + remainder;
    return value === 0 ? 24 : value;
  });
  return [hours];
}
